From 82fa3b2ab92f18ab87b9a48e7479aa4ce62f27ad Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:50:18 +0100
Subject: [PATCH] applets/notes: add actions to import and export a note

There was no way to save a note to a file or to load one, which makes
backups and moving notes around tedious. Two new actions in the widget's
context menu export the note as HTML or plain text and import such a file.

BUG: 517220
---
 applets/notes/noteshelper.cpp | 12 +++++++
 applets/notes/noteshelper.h   |  3 ++
 applets/notes/qml/main.qml    | 63 +++++++++++++++++++++++++++++++++++
 3 files changed, 78 insertions(+)

diff --git a/applets/notes/noteshelper.cpp b/applets/notes/noteshelper.cpp
index 0c826dc51..68014f4d4 100644
--- a/applets/notes/noteshelper.cpp
+++ b/applets/notes/noteshelper.cpp
@@ -9,6 +9,7 @@

 #include <QFile>
 #include <QIconEngine>
+#include <QSaveFile>
 #include <QUrl>

 #include "noteiconengine.h"
@@ -32,6 +33,17 @@ QString NotesHelper::fileContents(const QString &path) const
     return QString::fromUtf8(file.readAll());
 }

+bool NotesHelper::writeFile(const QUrl &url, const QString &contents) const
+{
+    QSaveFile file(url.toLocalFile());
+    if (!file.open(QIODevice::WriteOnly)) {
+        return false;
+    }
+
+    file.write(contents.toUtf8());
+    return file.commit();
+}
+
 QIcon NotesHelper::noteIcon(const QString &color) const
 {
     return QIcon{new NoteIconEngine{color}};
diff --git a/applets/notes/noteshelper.h b/applets/notes/noteshelper.h
index f8442080a..1e367b65a 100644
--- a/applets/notes/noteshelper.h
+++ b/applets/notes/noteshelper.h
@@ -7,6 +7,7 @@

 #include <QIcon>
 #include <QObject>
+#include <QUrl>
 #include <qqmlregistration.h>

 class NotesHelper : public QObject
@@ -22,5 +23,7 @@ public:

     Q_INVOKABLE QString fileContents(const QString &path) const;

+    Q_INVOKABLE bool writeFile(const QUrl &url, const QString &contents) const;
+
     Q_INVOKABLE QIcon noteIcon(const QString &color) const;
 };
diff --git a/applets/notes/qml/main.qml b/applets/notes/qml/main.qml
index 63a6409ba..2cac2e985 100644
--- a/applets/notes/qml/main.qml
+++ b/applets/notes/qml/main.qml
@@ -11,6 +11,7 @@ import QtQuick.Controls as QQC2 // just for desktop-styled context menus
 import QtQuick.Layouts
 import QtQuick.Window
 import QtQuick.Dialogs
+import QtCore

 import org.kde.draganddrop as DragDrop

@@ -678,6 +679,68 @@ PlasmoidItem {
         }
     }

+    Plasmoid.contextualActions: [
+        PlasmaCore.Action {
+            text: i18nc("@action:inmenu", "Import from File…")
+            icon.name: "document-import"
+            onTriggered: importDialog.open()
+        },
+        PlasmaCore.Action {
+            text: i18nc("@action:inmenu", "Export to File…")
+            icon.name: "document-export"
+            onTriggered: exportDialog.open()
+        },
+        PlasmaCore.Action {
+            isSeparator: true
+        }
+    ]
+
+    readonly property list<string> fileNameFilters: [
+        i18nc("@item:inlistbox file type", "HTML files (*.html *.htm)"),
+        i18nc("@item:inlistbox file type", "Text files (*.txt)"),
+    ]
+
+    function isHtmlFile(url: url): bool {
+        return /\.html?$/i.test(url.toString());
+    }
+
+    FileDialog {
+        id: importDialog
+        title: i18nc("@title:window", "Import Note")
+        nameFilters: [i18nc("@item:inlistbox file type", "HTML and text files (*.html *.htm *.txt)"), ...root.fileNameFilters, i18nc("@item:inlistbox file type", "All files (*)")]
+        currentFolder: StandardPaths.writableLocation(StandardPaths.DocumentsLocation)
+        onAccepted: {
+            let contents = NotesHelper.fileContents(selectedFile.toString());
+            if (!root.isHtmlFile(selectedFile)) {
+                contents = contents.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\n/g, "<br>");
+            }
+            root.mainTextArea.forceActiveFocus();
+            root.mainTextArea.insert(root.mainTextArea.cursorPosition, contents);
+        }
+    }
+
+    FileDialog {
+        id: exportDialog
+        title: i18nc("@title:window", "Export Note")
+        fileMode: FileDialog.SaveFile
+        defaultSuffix: "html"
+        nameFilters: root.fileNameFilters
+        currentFolder: StandardPaths.writableLocation(StandardPaths.DocumentsLocation)
+        onAccepted: {
+            const contents = root.isHtmlFile(selectedFile) ? root.mainTextArea.text : root.mainTextArea.getText(0, root.mainTextArea.length).replace(/[\u2028\u2029]/g, "\n");
+            if (!NotesHelper.writeFile(selectedFile, contents)) {
+                exportErrorDialog.open();
+            }
+        }
+    }
+
+    MessageDialog {
+        id: exportErrorDialog
+        title: i18nc("@title:window", "Export Failed")
+        text: i18nc("@info", "The note could not be saved to %1.", exportDialog.selectedFile.toString().replace(/^file:\/\//, ""))
+        buttons: MessageDialog.Ok
+    }
+
     PlasmaCore.ActionGroup {
         id: noteColorGroup
     }
